#!/usr/bin/env bash
set -euo pipefail
cd /workspaces/MRunning
test -f app.json && test -f src/components/TabBar.js || { echo "No estás en MRunning"; exit 1; }
mkdir -p assets src/components
BACKUP="/tmp/mrunning_icons_$(date +%Y%m%d_%H%M%S)"
mkdir -p "$BACKUP"
cp app.json "$BACKUP/"
cp src/components/TabBar.js "$BACKUP/"
cp src/components/TabIcons.js "$BACKUP/" 2>/dev/null || true
for f in icon.png adaptive-icon.png monochrome-icon.png; do test ! -f "assets/$f" || cp "assets/$f" "$BACKUP/$f"; done
echo "Respaldo: $BACKUP"
base64 -d > assets/adaptive-icon.png <<'PNG_ADAPTIVE_ICON'
