python3 - <<'PY_CONFIG'
import json
from pathlib import Path
p=Path('app.json')
cfg=json.loads(p.read_text())
expo=cfg['expo']
expo['icon']='./assets/icon.png'
expo['userInterfaceStyle']='automatic'
expo.setdefault('android',{}).setdefault('adaptiveIcon',{}).update({'foregroundImage':'./assets/adaptive-icon.png','backgroundColor':'#0A0C10','monochromeImage':'./assets/monochrome-icon.png'})
p.write_text(json.dumps(cfg,indent=2,ensure_ascii=False)+'\n')
PY_CONFIG
